import{j as e}from"./index-Q5tmBBoz.js";import{I as t}from"./InfoPage-CouG5ON_.js";import"./PageHeader-D19aNveu.js";function o(){return e.jsx(t,{title:"Equality and diversity",lead:"Brightwell is a community built on active inclusion. We are committed to a working and studying environment that welcomes every talent, from every background.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Equality policy"}],sections:[{heading:"Our policy",body:["The University’s equality policy sets out rights and responsibilities for students and staff, covering age, disability, gender identity, marriage and civil partnership, pregnancy and maternity, race, religion or belief, sex and sexual orientation.","The governing council owns the policy. Day-to-day leadership sits with the pro-vice-chancellor for equality and diversity, supported by an office that coordinates training, monitoring and reporting across all departments and colleges."],aside:{title:"Reporting & support",rows:[["Harassment advice","support@brightwell.ng"],["Student welfare","Student Welfare Services"],["Staff networks","8 employee networks"],["Equality reports","Published annually"]],links:[["/about","About the University"]]}},{heading:"What we are doing",body:["Inclusion is measured, not assumed. The University publishes an annual equality report with data on representation, attainment and pay across every protected characteristic, and each department maintains an action plan agreed with the equality office."],list:{title:"Current priorities",items:["Closing attainment and pay gaps through structured, anonymous review.","Disability access reviews of every college and department building by 2030.","An expanded staff and student mentoring programme.","Interfaith facilities and periods of reflection in colleges and the main campus."]}},{heading:"Dignity at work and study",body:["Everyone at Brightwell has the right to be treated with dignity. Bullying, harassment or victimisation of any kind is a disciplinary matter, and the University provides both formal procedures and informal confidential advice.","If you experience unacceptable behaviour — as a student, staff member or visitor — the support office can discuss your options without obligation to make a formal complaint."],aside:{title:"Who to contact",rows:[["Equality office","equality@brightwell.ng"],["Confidential advice","Network of trained advisors"],["Urgent support","Student welfare hotline"]]}}]})}export{o as default};
